export const LP_STATS_FILTER_CHANGED="lp-stats:filter-changed";export const LP_STATS_EXPORT_CSV="lp-stats:export-csv";export const LP_STATS_RANGE_RESOLVED="lp-stats:range-resolved";const COMPARE_DEFAULT="previous_period";export class LpStatsState{constructor(){const t=new URL(window.location.href).searchParams;this.filters={filtertype:t.get("filtertype")||"today",date:t.get("date")||"",compare:"previous_year"===t.get("compare")?"previous_year":COMPARE_DEFAULT,instructor_id:parseInt(t.get("instructor_id"),10)||0,category_id:parseInt(t.get("category_id"),10)||0}}get(){return{...this.filters}}set(t={}){this.filters={...this.filters,...t},this.syncUrl(),document.dispatchEvent(new CustomEvent(LP_STATS_FILTER_CHANGED,{detail:this.get()}))}syncUrl(){if(!window.history||"function"!=typeof window.history.replaceState)return;const t=new URL(window.location.href),e=t.searchParams,{filtertype:r,date:i,compare:s,instructor_id:a,category_id:o}=this.filters;this.writeParam(e,"filtertype",r&&"today"!==r?r:""),this.writeParam(e,"date",i),this.writeParam(e,"compare",s&&s!==COMPARE_DEFAULT?s:""),this.writeParam(e,"instructor_id",a>0?String(a):""),this.writeParam(e,"category_id",o>0?String(o):""),window.history.replaceState(null,"",t.toString())}writeParam(t,e,r){r?t.set(e,r):t.delete(e)}}export const lpStatsState=new LpStatsState;